  {"claim": "P03180 had a PCP clinic encounter (E004756) 16:29:15-16:59:15 the same day, overlapping the access window.", "sources": ["G6", "L1", "L24"]},
  {"claim": "U0228 is connected to encounter E004756 as care team, and to the patient via department-of-encounter and department co-worker links in PCP.", "sources": ["G9", "G10", "G8"]},
  {"claim": "Access occurred only on PCP workstations (D0149, D0310, D0050) using read, create, update, print, and query actions consistent with clinic documentation activity.", "sources": ["L1", "L13", "L14", "L23", "G12", "G13", "G17", "G21"]}
